import LinkedInIcon from '@mui/icons-material/LinkedIn';
import PinterestIcon from '@mui/icons-material/Pinterest';
import PlatformCard from 'views/commons/cards/PlatformCard';
import useSnackbar from 'hooks/useSnackbar';
import useAuth from 'hooks/useAuth';

const platforms = [
    {
        text: 'Add Tiktok profile',
        icon: <img src="https://cdn-icons-png.flaticon.com/512/3046/3046122.png" alt="tiktok" width={20} />,
        id: 'tiktok',
        color: '#FE2C55'
    },
    {
        text: 'Add Facebook profile',
        icon: <FacebookIcon sx={{ color: '#1877F2' }} />,
        id: 'facebook',
        color: '#1877F2'
    },
    {
        text: 'Add Facebook group',
        icon: <FacebookIcon sx={{ color: '#1877F2' }} />,
        id: 'facebook-group',
        color: '#1877F2'
    },
    {
        text: 'Add Facebook page',
        icon: <FacebookIcon sx={{ color: '#1877F2' }} />,
        id: 'facebook-page',
        color: '#1877F2'
    },
    {
        text: 'Add Instagram profile',
        icon: <InstagramIcon sx={{ color: '#E1306C' }} />,
        id: 'instagram',
        color: '#E1306C'
    },
    {
        text: 'Add XTwitter profile',
        icon: <TwitterIcon sx={{ color: '#1DA1F2' }} />,
        id: 'twitter',
        color: '#1DA1F2'
    },
    {
        text: 'Add Youtube channel',
        icon: <YouTubeIcon sx={{ color: '#FF0000' }} />,
        id: 'youtube',
        color: '#FF0000'
    },
    {
        text: 'Add LinkedIn profile',
        icon: <LinkedInIcon sx={{ color: '#0077B5' }} />,
        id: 'linkedin',
        color: '#0077B5'
    },
    {
        text: 'Add LinkedIn page',
        icon: <LinkedInIcon sx={{ color: '#0077B5' }} />,
        id: 'linkedin-page',
        color: '#0077B5'
    },
    // {
    //     text: 'Add Pinterest board',
    //     icon: <PinterestIcon sx={{ color: '#E60023' }} />,
    //     id: 'pinterest',
    //     color: '#E60023'
    // },
    {
        text: 'Add WordPress Profile',
        icon: <img src="https://cdn-icons-png.flaticon.com/512/174/174881.png" alt="wordpress" width={20} />,
        id: 'wordpress',
        color: '#21759B'
    },
    {
        text: 'Add WordPress.org Profile',
        icon: <img src="https://cdn-icons-png.flaticon.com/512/174/174881.png" alt="wordpress" width={20} />,
        id: 'wordpress-org',
        color: '#21759B'
    }
];

const SocialMediaManager = () => {
    const { user } = useAuth();
    const theme = useTheme();
    const isSmallScreen = useMediaQuery(theme.breakpoints.down('md'));
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const { showSnackbar } = useSnackbar();
    const [dataMap, setDataMap] = useState({});
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState(null);
    const [deleteDialogOpen, setDeleteDialogOpen] = React.useState(false);
    const [selectedIds, setSelectedIds] = React.useState([]);

    const [facebookModalOpen, setFacebookModalOpen] = useState(false);
    const [facebookAccounts, setFacebookAccounts] = useState([]);
    const [selectedAccount, setSelectedAccount] = useState(null);
    const [facebookPages, setFacebookPages] = useState([]);
    const [selectedPage, setSelectedPage] = useState(null);
    const [loadingPages, setLoadingPages] = useState(false);

    const handleFacebookPageAdd = async () => {
        setFacebookModalOpen(true);

        try {
            // Fetch connected Facebook accounts
            const accountsResponse = await ApiRequest('GET', 'all-social-profiles-data?platform=facebook');
            setFacebookAccounts(accountsResponse.data || []);
        } catch (error) {
            showSnackbar('Failed to fetch Facebook accounts', 'error');
            console.error('Facebook accounts error:', error);
        }
    };

    const fetchFacebookPages = async (accountId) => {
        setLoadingPages(true);
        try {
            const pagesResponse = await ApiRequest('GET', `facebook/pages?account_id=${accountId}`);
            setFacebookPages(pagesResponse.data || []);
        } catch (error) {
            showSnackbar('Failed to fetch Facebook pages', 'error');
            console.error('Facebook pages error:', error);
        } finally {
            setLoadingPages(false);
        }
    };

    const handleAccountSelect = (account) => {
        setSelectedAccount(account);
        fetchFacebookPages(account.id);
    };

    const resetModalState = () => {
        setSelectedAccount(null);
        setSelectedPage(null);
        setFacebookPages([]);
    };

    // Close sidebar by default on medium and small screens
    useEffect(() => {
        setSidebarOpen(!isSmallScreen);
    }, [isSmallScreen]);

    const fetchSocialData = async () => {
        try {
            const response = await ApiRequest('GET', `all-social-profiles-data?pagination=false&formatData=false`);
            setDataMap(response?.data || {});
        } catch (error) {
            showSnackbar(error.message, 'error');
        }
    };

    useEffect(() => {
        fetchSocialData();
    }, []);

    const handleAddPage = async () => {
        if (!selectedPage) {
            showSnackbar('Please select a page', 'error');
            return;
        }

        try {
            const response = await ApiRequest('POST', 'facebook/add-page', {
                page_id: selectedPage.id,
                access_token: selectedPage.access_token
                // ... other required data ...
            });

            if (response.success) {
                showSnackbar('Page added successfully!', 'success');
                fetchSocialData(); // Refresh data
            } else {
                showSnackbar(response.message || 'Failed to add page', 'error');
            }
        } catch (error) {
            showSnackbar('Failed to add Facebook page', 'error');
            console.error('Add page error:', error);
        } finally {
            setFacebookModalOpen(false);
            resetModalState();
        }
    };

    // Handle adding a new platform
    const handleAdd = async (platform) => {
        if (platform.id === 'facebook-page') {
            handleFacebookPageAdd();
            return;
        }
        setLoading(true);
        setError(null);

        try {
            // Only proceed if it's TikTok (though this will be called for all platforms)
            if (!user.id) {
                alert('user id not doun');
            }

            const payload = {
                user_id: user.id
            };
            let response;

            const finalPayload = { ...payload };
            console.log('finalPayload', finalPayload);

            switch (platform.id) {
                case 'tiktok':
                    response = await ApiRequest('GET', 'platform/tiktok-connect', null, finalPayload);
                    break;
                case 'instagram':
                    response = await ApiRequest('GET', 'instagram/connect', finalPayload);
                    break;
                case 'facebook-group':
                    response = await ApiRequest('GET', 'facebook/connect', { ...finalPayload, type: 'fa-group' });
                    break;
                case 'facebook':
                    response = await ApiRequest('GET', 'facebook/connect', finalPayload);
                    break;
                case 'twitter':
                    response = await ApiRequest('GET', 'twitter/connect', finalPayload);
                    break;
                case 'youtube':
                    response = await ApiRequest('GET', 'youtube/connect', finalPayload);
                    break;
                default:
                    throw new Error(`Unsupported platform: ${platform.id}`);
            }
            // 1. Get TikTok auth URL from backend

            if (!response || !response.data) {
                throw new Error(response.message || 'Failed to get social media auth URL');
            }

            window.location.href = response?.data?.result?.data;
        } catch (err) {
            setError(err.message || 'Failed to connect TikTok account');
            console.error('TikTok auth error:', err);
        } finally {
            setLoading(false);
        }
    };
    // Handle searching profiles
    const handleSearch = async (platformId, username) => {
        console.log('API search called with:', {
            platformId,
            username
        });

        try {
            setLoading(true);
            const endpoint = username.trim()
                ? `all-social-profiles-data?pagination=false&user_name=${username}&platform=${platformId}`
                : `all-social-profiles-data?pagination=false`;

            console.log('API endpoint:', endpoint);

            const response = await ApiRequest('GET', endpoint);

            console.log('API response:', response);

            setDataMap((prev) => ({
                ...prev,
                [platformId]: response?.data?.[platformId] || response?.data || []
            }));
        } catch (error) {
            console.error('Search error:', error);
            showSnackbar(error.message, 'error');
            setDataMap((prev) => prev);
        } finally {
            setLoading(false);
        }
    };
    // Handle deleting selected profiles
    const handleDelete = async (platformId, selectedIds) => {
        console.log(`Selected in ${platformId}:`, selectedIds);
        if (selectedIds.length === 0) return;
        setSelectedIds(selectedIds);
        setDeleteDialogOpen(true);
    };

    // Handle selecting individual profiles
    const handleSelect = (platformId, selectedIds) => {
        console.log(`Selected in ${platformId}:`, selectedIds);
        setSelectedIds(selectedIds);
        // You might want to store the selected items in state
        // or perform other actions with them
    };

    // Handle selecting all profiles
    const handleSelectAll = (platformId, selectedIds) => {
        console.log(`Selected all in ${platformId}:`, selectedIds);
        setSelectedIds(selectedIds);
        // You might want to store the selected items in state
        // or perform other actions with them
    };
    return (
        <>
            <Grid container sx={{ minHeight: '100vh', backgroundColor: '#f8f9fa' }}>
                {/* Sidebar */}
                <Grid
                    item
                    xs={sidebarOpen ? 12 : 0}
                    md={sidebarOpen ? 3 : 0}
                    lg={sidebarOpen ? 2.5 : 0}
                    sx={{
                        display: sidebarOpen ? 'block' : 'none',
                        position: isSmallScreen ? 'fixed' : 'relative',
                        height: '100vh',
                        zIndex: 1100,
                        backgroundColor: 'white',
                        boxShadow: isSmallScreen ? 3 : '0 2px 10px rgba(0,0,0,0.05)',
                        transition: 'width 0.3s ease'
                    }}
                >
                    {/* Sidebar content (same as before) */}
                    <Box
                        sx={{
                            p: 1.5,
                            borderBottom: '1px solid #f0f0f0',
                            backgroundColor: '#ffffff',
                            pt: isSmallScreen ? 8 : 2
                        }}
                    >
                        <Typography
                            component="h1"
                            sx={{
                                mb: 1.5,
                                fontWeight: '600',
                                color: '#333',
                                fontSize: '0.95rem',
                                letterSpacing: '0.2px',
                                pl: 1
                            }}
                        >
                            Social Media
                        </Typography>
                        <TextField
                            fullWidth
                            placeholder="Search..."
                            size="small"
                            sx={{
                                mb: 0.5,
                                backgroundColor: '#f8f9fa',
                                borderRadius: '6px',
                                '& .MuiOutlinedInput-root': {
                                    '& fieldset': {
                                        borderColor: 'transparent'
                                    },
                                    '&:hover fieldset': {
                                        borderColor: '#4caf50'
                                    },
                                    '&.Mui-focused fieldset': {
                                        borderColor: '#4caf50',
                                        borderWidth: '1px'
                                    }
                                }
                            }}
                            InputProps={{
                                startAdornment: (
                                    <InputAdornment position="start">
                                        <SearchIcon fontSize="small" sx={{ color: '#9e9e9e' }} />
                                    </InputAdornment>
                                ),
                                sx: {
                                    fontSize: '0.8rem',
                                    height: '34px'
                                }
                            }}
                        />
                    </Box>
                    <DeleteAlert
                        open={deleteDialogOpen}
                        onClose={() => setDeleteDialogOpen(false)}
                        selectedIds={selectedIds}
                        endpoint="delete-profiles-data"
                        onDeleteSuccess={() => {
                            showSnackbar('Employe deleted successfully!', 'success');
                            setDeleteDialogOpen(false);
                            fetchSocialData();
                            setSelectedIds([]); // ✅ Clear selection after delete
                        }}
                        message="Are you Employe you want to delete the selected permissions?"
                    />

                    {/* Platform List */}
                    <Box
                        sx={{
                            flex: 1,
                            overflowY: 'auto',
                            '&::-webkit-scrollbar': {
                                width: '4px'
                            },
                            '&::-webkit-scrollbar-thumb': {
                                backgroundColor: '#e0e0e0',
                                borderRadius: '4px'
                            }
                        }}
                    >
                        <List sx={{ py: 0 }}>
                            {platforms.map((item, index) => (
                                <ListItem
                                    key={index}
                                    button
                                    onClick={() => handleAdd(item)}
                                    sx={{
                                        height: 38,
                                        py: 0,
                                        px: 1.5,
                                        '&:hover': {
                                            backgroundColor: '#f5f5f5'
                                        },
                                        transition: 'background-color 0.2s ease'
                                    }}
                                >
                                    <ListItemIcon sx={{ minWidth: 30, color: '#555' }}>{item.icon}</ListItemIcon>
                                    <ListItemText
                                        primary={item.text}
                                        primaryTypographyProps={{
                                            noWrap: true,
                                            fontSize: '0.75rem',
                                            fontWeight: '500',
                                            color: '#555'
                                        }}
                                        sx={{ my: 0 }}
                                    />
                                </ListItem>
                            ))}
                        </List>
                    </Box>
                </Grid>
                <Grid
                    item
                    xs={12}
                    md={sidebarOpen ? 9 : 12}
                    lg={sidebarOpen ? 9.5 : 12}
                    sx={{
                        // ml: isSmallScreen ? 0 : sidebarOpen ? 0 : 0,
                        p: 2,
                        backgroundColor: '#f8f9fa'
                    }}
                >
                    <Box
                        sx={{
                            display: 'flex',
                            justifyContent: 'space-between',
                            alignItems: 'center',
                            mb: 2,
                            backgroundColor: '#ffffff',
                            p: 1.5,
                            borderRadius: '6px',
                            boxShadow: '0 1px 2px rgba(0,0,0,0.05)',
                            border: '1px solid #eaeaea'
                        }}
                    >
                        <Typography
                            variant="h6"
                            sx={{
                                fontWeight: '600',
                                color: '#333',
                                fontSize: '1rem',
                                letterSpacing: '0.2px'
                            }}
                        >
                            Manage Platforms
                        </Typography>
                        <Button
                            variant="contained"
                            startIcon={<AddIcon />}
                            sx={{
                                backgroundColor: '#4caf50',
                                borderRadius: '6px',
                                textTransform: 'none',
                                px: 1.5,
                                py: 0.6,
                                fontSize: '0.75rem',
                                fontWeight: '500',
                                boxShadow: 'none',
                                '&:hover': {
                                    backgroundColor: '#3d8b40',
                                    boxShadow: 'none'
                                },
                                transition: 'all 0.2s ease'
                            }}
                        >
                            Create Post
                        </Button>
                    </Box>

                    {(() => {
                        if (loading) {
                            return (
                                <Box display="flex" justifyContent="center" alignItems="center" height="200px">
                                    <CircularProgress />
                                </Box>
                            );
                        }

                        if (error) {
                            return (
                                <Box display="flex" justifyContent="center" alignItems="center" height="200px">
                                    <Typography color="error">{error}</Typography>
                                </Box>
                            );
                        }

                        return (
                            <Grid container spacing={1}>
                                {platforms.map((platform, index) => (
                                    <Grid item xs={12} md={6} lg={6} key={index}>
                                        <PlatformCard
                                            platform={platform}
                                            data={dataMap[platform.id] || []}
                                            onAdd={() => handleAdd(platform)}
                                            onSearch={(query) => handleSearch(platform.id, query)}
                                            onDelete={(selected) => handleDelete(platform.id, selected)}
                                            onSelect={(selected) => handleSelect(platform.id, selected)}
                                            onSelectAll={(selected) => handleSelectAll(platform.id, selected)}
                                            loading={loading}
                                        />
                                    </Grid>
                                ))}
                            </Grid>
                        );
                    })()}
                </Grid>
            </Grid>
            <Dialog
                open={facebookModalOpen}
                onClose={() => {
                    setFacebookModalOpen(false);
                    resetModalState();
                }}
                maxWidth="md"
                fullWidth
                sx={{
                    '& .MuiPaper-root': {
                        backgroundColor: theme.palette.text.primary // Change dialog background color
                    }
                }}
            >
                <DialogTitle sx={{ display: 'flex', alignItems: 'center', background: 'white' }}>
                    <FacebookIcon sx={{ color: '#1877F2', mr: 1 }} />
                    Add Facebook Page
                </DialogTitle>

                <DialogContent dividers>
                    {/* Step 1: Select Account */}
                    {!selectedAccount ? (
                        <Box sx={{ background: 'white' }}>
                            <Typography variant="h6" gutterBottom>
                                Select a Facebook Account
                            </Typography>
                            {facebookAccounts.length > 0 ? (
                                <List>
                                    {facebookAccounts.map((account) => (
                                        <ListItem
                                            button
                                            key={account.id}
                                            onClick={() => handleAccountSelect(account)}
                                            sx={{
                                                '&:hover': { backgroundColor: '#f5f5f5' },
                                                borderRadius: 1,
                                                mb: 1
                                            }}
                                        >
                                            <ListItemIcon>
                                                <FacebookIcon sx={{ color: '#1877F2' }} />
                                            </ListItemIcon>
                                            <ListItemText
                                                primary={account.user_name}
                                                primaryTypographyProps={{ sx: { color: '#1877F2', fontWeight: 600, fontSize: '1.1rem' } }}
                                            />
                                        </ListItem>
                                    ))}
                                </List>
                            ) : (
                                <Box textAlign="center" py={3}>
                                    <Typography variant="body1" color="textSecondary">
                                        No Facebook accounts connected
                                    </Typography>
                                    <Button
                                        variant="contained"
                                        color="primary"
                                        sx={{ mt: 2 }}
                                        onClick={() => handleAdd({ id: 'facebook' })}
                                    >
                                        Connect Facebook Account
                                    </Button>
                                </Box>
                            )}
                        </Box>
                    ) : (
                        // Step 2: Select Page for selected account
                        <Box>
                            <Typography variant="h6" gutterBottom>
                                Select a Page for {selectedAccount.name}
                            </Typography>

                            {(() => {
                                if (loadingPages) {
                                    return (
                                        <Box display="flex" justifyContent="center" py={3}>
                                            <CircularProgress />
                                        </Box>
                                    );
                                }

                                if (facebookPages.length > 0) {
                                    return (
                                        <List>
                                            {facebookPages.map((page) => (
                                                <ListItem
                                                    button
                                                    key={page.id}
                                                    selected={selectedPage?.id === page.id}
                                                    onClick={() => setSelectedPage(page)}
                                                    sx={{
                                                        '&:hover': { backgroundColor: '#f5f5f5' },
                                                        borderRadius: 1,
                                                        mb: 1
                                                    }}
                                                >
                                                    <ListItemIcon>
                                                        <img
                                                            src={page.picture?.data?.url || 'https://via.placeholder.com/40'}
                                                            alt={page.name}
                                                            width={40}
                                                            height={40}
                                                            style={{ borderRadius: '50%' }}
                                                        />
                                                    </ListItemIcon>
                                                    <ListItemText primary={page.name} secondary={`${page.fan_count || 0} followers`} />
                                                </ListItem>
                                            ))}
                                        </List>
                                    );
                                }

                                return (
                                    <Box textAlign="center" py={3}>
                                        <Typography variant="body1" color="textSecondary">
                                            No pages found for this account
                                        </Typography>
                                    </Box>
                                );
                            })()}
                        </Box>
                    )}
                </DialogContent>

                <DialogActions>
                    <Button
                        onClick={() => {
                            setFacebookModalOpen(false);
                            resetModalState();
                        }}
                    >
                        Cancel
                    </Button>
                    {selectedAccount && (
                        <Button variant="contained" color="primary" disabled={!selectedPage} onClick={handleAddPage}>
                            Add Page
                        </Button>
                    )}
                </DialogActions>
            </Dialog>
        </>
    );
};

export default SocialMediaManager;
